const raw = `{
  "shift_summary": "Identity shift on 2026-11-21 from 00:00 to 08:00 UTC. Evelyn Brooks handed off to Daniel Rivera.",
  "open_items": [
    {
      "ticket": "IDN-221",
      "service": "Account Recovery Service",
      "status": "Recovery emails are arriving late for some users.",
      "severity": "SEV3",
      "owner": "Daniel Rivera",
      "next_action": "Check email delivery times at 08:15 UTC."
    }
  ],
  "watch_list": [
    "Watch Account Recovery Service for recovery email delays above five minutes."
  ],
  "recently_resolved": [
    "IDN-219, Account Sign-In Service. The sign-in error alert cleared at 05:42 UTC."
  ],
  "open_questions": []
}`;
const handoff=JSON.parse(raw);
const fieldsMatch=(o,keys)=>o!==null && typeof o==="object" && !Array.isArray(o) && Object.keys(o).length===keys.length && keys.every(k=>Object.hasOwn(o,k));
const isText=s=>typeof s==="string" && s.length>0;
const entryFields=["ticket","service","status","severity","owner","next_action"];
const sections=["watch_list","recently_resolved","open_questions"];
if(!fieldsMatch(handoff,["shift_summary","open_items",...sections]) || !isText(handoff.shift_summary) || !Array.isArray(handoff.open_items) || !handoff.open_items.every(item=>fieldsMatch(item,entryFields) && entryFields.every(k=>isText(item[k])) && ["SEV1","SEV2","SEV3","SEV4","Unknown"].includes(item.severity)) || !sections.every(k=>Array.isArray(handoff[k]) && handoff[k].every(isText))) throw Error("Handoff does not match the schema");
text("JSON passed all constraints in handoff.schema.json.");
